for name, url in images:
    raw_path = TMP / f"{Path(name).stem}.heic"
    download_file(url, raw_path)
    with Image.open(raw_path) as img:
        img = ImageOps.exif_transpose(img).convert("RGB")
        img.save(OUT / name, quality=92, optimize=True)
